import fitz, collections
d=fitz.open('realplan.pdf')
for pg,name in [(32,'M101'),(31,'MD101')]:
    p=d[pg]
    cnt=0; other=0
    for dr in p.get_drawings():
        r=dr['rect']
        if 27.5<r.width<29.5 and 23.5<r.height<25.5:
            types=collections.Counter(it[0] for it in dr['items'])
            if all(t=='l' for t in types) and len(dr['items'])==6: cnt+=1
            else:
                other+=1
                if other<6: print(name,'OTHER',dict(types),r)
    print(name,'hex6',cnt,'othersize-match',other)
